function usage(): never {
    fwrite(STDERR,"Usage:\n  O8_DEMO_DATA=1 php bin/demo-data.php list\n  O8_DEMO_DATA=1 php bin/demo-data.php create --tenant=ID --confirm=CREATE-DEMO-DATA\n  O8_DEMO_DATA=1 php bin/demo-data.php reset  --tenant=ID --confirm=RESET-DEMO-DATA\n"); exit(2);
}
function option(string $name): ?string { global $argv; foreach ($argv as $arg) if (str_starts_with($arg,'--'.$name.'=')) return substr($arg,strlen($name)+3); return null; }
function pdf(string $text): string {
    $text=str_replace(['\\','(',')'],['\\\\','\\(', '\\)'],$text); $stream="BT /F1 18 Tf 48 730 Td ($text) Tj ET";
    $objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '.strlen($stream).' >>' . "\nstream\n$stream\nendstream"];
    $out="%PDF-1.4\n"; $offsets=[]; foreach ($objects as $i=>$object) { $offsets[] = strlen($out); $out.=($i+1)." 0 obj\n$object\nendobj\n"; } $xref=strlen($out); $out.="xref\n0 6\n0000000000 65535 f \n"; foreach ($offsets as $offset) $out.=str_pad((string)$offset,10,'0',STR_PAD_LEFT)." 00000 n \n"; return $out."trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n$xref\n%%EOF\n";
}
function actorRow(PDO $db,int $tenant): array {
    $s=$db->prepare('SELECT u.*,a.id AS account_id,a.auth_version AS account_auth_version,a.must_change_password,t.name AS tenant_name,t.public_id AS tenant_uuid FROM users u JOIN accounts a ON a.id=u.account_id JOIN tenants t ON t.id=u.tenant_id WHERE u.tenant_id=? AND u.active=1 AND a.active=1 AND a.must_change_password=0 ORDER BY CASE u.role WHEN \'admin\' THEN 0 ELSE 1 END,u.id'); $s->execute([$tenant]); return $s->fetchAll();
}
function erase(PDO $db,Storage $storage,Actor $actor): int {
    $s=$db->prepare("SELECT f.relative_path FROM document_files f JOIN documents d ON d.tenant_id=f.tenant_id AND d.id=f.document_id WHERE d.tenant_id=? AND d.source_type='demo'"); $s->execute([$actor->tenantId()]); $paths=$s->fetchAll(PDO::FETCH_COLUMN);
    [, $target]=$storage->paths($storage->location($actor)?:throw new RuntimeException('Geprüfte Ablage fehlt.'));
    foreach ($paths as $relative) { if (!preg_match('/^[a-f0-9]{48}\.(pdf|png|jpg)$/D',$relative)) throw new RuntimeException('Unerwarteter Demo-Dateipfad. Reset abgebrochen.'); $path=$target.'/'.$relative; if (is_link($path)) throw new RuntimeException('Demo-Dateipfad ist ein Symlink. Reset abgebrochen.'); if (is_file($path) && !@unlink($path)) throw new RuntimeException('Demo-Datei konnte nicht entfernt werden. Reset abgebrochen.'); }
    $db->beginTransaction(); try {
        $s=$db->prepare("SELECT COUNT(*) FROM documents WHERE tenant_id=? AND source_type='demo' FOR UPDATE"); $s->execute([$actor->tenantId()]); $count=(int)$s->fetchColumn();
        $s=$db->prepare("DELETE FROM documents WHERE tenant_id=? AND source_type='demo'"); $s->execute([$actor->tenantId()]);
        $s=$db->prepare("UPDATE accounting_accounts aa SET active=0 WHERE aa.tenant_id=? AND aa.name LIKE '[DEMO] %' AND NOT EXISTS (SELECT 1 FROM document_invoices di WHERE di.tenant_id=aa.tenant_id AND di.account_id=aa.id) AND NOT EXISTS (SELECT 1 FROM invoice_items ii WHERE ii.tenant_id=aa.tenant_id AND ii.account_id=aa.id)"); $s->execute([$actor->tenantId()]);
        $folders=$db->prepare("SELECT id FROM folders WHERE tenant_id=? AND name LIKE '[DEMO] %' ORDER BY parent_id DESC,id DESC"); $folders->execute([$actor->tenantId()]); foreach ($folders->fetchAll(PDO::FETCH_COLUMN) as $id) { $check=$db->prepare('SELECT 1 FROM folder_documents WHERE tenant_id=? AND folder_id=? LIMIT 1'); $check->execute([$actor->tenantId(),$id]); if (!$check->fetchColumn()) { $delete=$db->prepare('DELETE FROM folders WHERE tenant_id=? AND id=?'); $delete->execute([$actor->tenantId(),$id]); } }
        $tags=$db->prepare("SELECT id FROM tags WHERE tenant_id=? AND name LIKE 'DEMO · %'"); $tags->execute([$actor->tenantId()]); foreach ($tags->fetchAll(PDO::FETCH_COLUMN) as $id) { $check=$db->prepare('SELECT 1 FROM document_tags WHERE tenant_id=? AND tag_id=? LIMIT 1'); $check->execute([$actor->tenantId(),$id]); if (!$check->fetchColumn()) { $delete=$db->prepare('DELETE FROM tags WHERE tenant_id=? AND id=?'); $delete->execute([$actor->tenantId(),$id]); } }
        $db->commit(); return $count;
    } catch (Throwable $error) { if ($db->inTransaction()) $db->rollBack(); throw $error; }
}

try {
    if (getenv('O8_DEMO_DATA')!=='1') throw new RuntimeException('Sicherheitsstopp: O8_DEMO_DATA=1 muss ausdrücklich gesetzt sein.');
    $command=$argv[1]??''; $tenant=option('tenant'); if (!in_array($command,['list','create','reset'],true)) usage();
    if ($command!=='list' && (!ctype_digit((string)$tenant) || (int)$tenant<1)) usage();
    if ($command!=='list' && option('confirm')!==($command==='create'?'CREATE-DEMO-DATA':'RESET-DEMO-DATA')) throw new RuntimeException('Sicherheitsstopp: Bestätigung stimmt nicht.');
    $root=dirname(__DIR__); $config=Config::load($root); if (!$config) throw new RuntimeException('Lokale Konfiguration fehlt.'); $db=Database::connect($config['database']); $runtime=new Runtime($root.'/storage/system'); $migrator=new Migrator($db,$root.'/database/migrations'); if (!$migrator->installed($runtime->identity()) || !$migrator->current()) throw new RuntimeException('Installation oder Schemaaktualisierung fehlt.');
    if ($command==='list') {
        $rows=$db->query("SELECT t.id,t.name,t.active,s.root_path,COUNT(d.id) AS documents FROM tenants t LEFT JOIN storage_locations s ON s.tenant_id=t.id AND s.storage_key='main' AND s.active=1 LEFT JOIN documents d ON d.tenant_id=t.id GROUP BY t.id,t.name,t.active,s.root_path ORDER BY t.name,t.id")->fetchAll();
        printf("%-6s %-28s %-9s %-10s %s\n",'ID','Mandant','Status','Dokumente','Storage');
        foreach ($rows as $row) printf("%-6d %-28s %-9s %-10d %s\n",$row['id'],mb_strimwidth($row['name'],0,28,'…'),$row['active']?'aktiv':'inaktiv',$row['documents'],$row['root_path']?:'–');
        exit;
    }
    $rows=actorRow($db,(int)$tenant); if (!$rows) throw new RuntimeException('Mandant benötigt mindestens einen aktiven Benutzer mit geändertem Startpasswort.'); $actors=array_map(static fn($row)=>new Actor('tenant',$row),$rows); $admin=current(array_filter($actors,static fn(Actor $actor)=>$actor->row['role']==='admin')) ?: throw new RuntimeException('Mandant benötigt einen aktiven Admin.'); $storage=new Storage($db,$root); $docs=new Documents($db,$root); $storage->paths($storage->location($admin)?:throw new RuntimeException('Geprüfte Ablage für diesen Mandanten fehlt.'));
    if ($command==='reset') { echo 'Entfernt: '.erase($db,$storage,$admin)." Demo-Dokumente.\n"; exit; }
    $nonDemo=$db->prepare("SELECT COUNT(*) FROM documents WHERE tenant_id=? AND source_type<>'demo'"); $nonDemo->execute([$admin->tenantId()]); if ((int)$nonDemo->fetchColumn()) throw new RuntimeException('Sicherheitsstopp: Der Mandant enthält nicht als Demo markierte Dokumente. Nur einen leeren Testmandanten verwenden.');
    $existing=$db->prepare("SELECT COUNT(*) FROM documents WHERE tenant_id=? AND source_type='demo'"); $existing->execute([$admin->tenantId()]); if ((int)$existing->fetchColumn()) throw new RuntimeException('Demo-Bestand existiert bereits. Zuerst den Reset ausführen.');
    $settings=$docs->accountingSettings($admin); $rates=array_map(static fn($row)=>(string)(float)$row['rate'],array_filter($settings['vatRates'],static fn($row)=>(bool)$row['active'])); foreach (['0','7','19'] as $rate) if (!in_array($rate,$rates,true)) $rates[]=$rate; $accounts=array_map(static fn($row)=>['code'=>$row['code'],'name'=>$row['name']],array_filter($settings['accounts'],static fn($row)=>(bool)$row['active'])); foreach ([['DEMO-100','[DEMO] Bürobedarf'],['DEMO-200','[DEMO] Dienstleistungen'],['DEMO-300','[DEMO] Reiseaufwand']] as $account) if (!array_filter($accounts,static fn($row)=>$row['code']===$account[0])) $accounts[]=['code'=>$account[0],'name'=>$account[1]]; $docs->saveAccountingSettings($admin,['framework'=>$settings['framework']?:'Demo-Kontenplan','vatRates'=>$rates,'accounts'=>$accounts]);
    $tagNames=['DEMO · Rechnung','DEMO · Vertrag','DEMO · Reise','DEMO · Haushalt','DEMO · Steuer']; foreach ($tagNames as $name) { if (!array_filter($docs->tags($admin),static fn($tag)=>$tag['name']===$name)) $docs->createTag($admin,$name); } $tags=[]; foreach ($docs->tags($admin) as $tag) $tags[$tag['name']]=$tag['id'];
    foreach ([['[DEMO] Finanzen',null],['[DEMO] Rechnungen','[DEMO] Finanzen'],['[DEMO] Verträge',null],['[DEMO] Privat',null]] as [$name,$parentName]) { $found=array_filter($docs->folders($admin),static fn($folder)=>$folder['name']===$name); if (!$found) { $parent=null; if ($parentName) { $parent=array_values(array_filter($docs->folders($admin),static fn($folder)=>$folder['name']===$parentName))[0]['id']; } $docs->folderWrite($admin,'create',0,$name,$parent); } } $folders=[]; foreach ($docs->folders($admin) as $folder) $folders[$folder['name']]=$folder['id'];
    $tmp=sys_get_temp_dir().'/o8-demo.'.bin2hex(random_bytes(8)); if (!mkdir($tmp,0700)) throw new RuntimeException('Temporäres Verzeichnis kann nicht angelegt werden.');
    $senders=['Nordlicht Energie','Bürobedarf Hansen','Muster Reisen GmbH','Versicherung Nord','Stadtwerke Fiktiv','Kanzlei Beispiel']; $types=['invoice','document','contract','certificate','credit_note']; $placements=['[DEMO] Rechnungen','[DEMO] Finanzen','[DEMO] Verträge',null,'[DEMO] Privat']; $created=[];
    try { for ($i=1;$i<=24;$i++) { $kind=$i%8===0?'png':($i%11===0?'jpg':'pdf'); $name=sprintf('[DEMO] Beleg %02d.%s',$i,$kind); $source=$tmp.'/'.$name; if ($kind==='pdf') file_put_contents($source,pdf('[DEMO] '.$senders[$i%count($senders)].' · Beleg '.$i)); elseif ($kind==='png') file_put_contents($source,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScL9xQAAAABJRU5ErkJggg==',true)); else file_put_contents($source,base64_decode('',true)); $owner=$actors[($i-1)%count($actors)]; $id=$docs->ingest($owner,$source,$name,'demo'); $doc=$docs->get($owner,$id); $tag=[$tags[$i%3===0?'DEMO · Reise':($i%2?'DEMO · Rechnung':'DEMO · Haushalt')]]; $docs->save($owner,$id,(int)$doc['revision'],['title'=>sprintf('[DEMO] %s · %02d',$senders[$i%count($senders)],$i),'sender'=>$senders[$i%count($senders)],'reference'=>sprintf('DEMO-%04d',$i),'date'=>sprintf('2026-%02d-%02d',1+(($i-1)%9),1+(($i*3)%27)),'memo'=>'Vollständig fiktiver Demo-Beleg für Suche und Abnahme.','documentType'=>$types[$i%count($types)],'tags'=>$tag]); $doc=$docs->get($admin,$id); if (($folder=$placements[$i%count($placements)])!==null) $docs->link($admin,$id,(int)$doc['revision'],$folders[$folder],false); if ($i%3===0) { $doc=$docs->get($admin,$id); $accountsByCode=[]; foreach ($docs->accounting($admin)['accounts'] as $account) $accountsByCode[$account['code']]=$account['id']; $docs->saveInvoice($admin,$id,(int)$doc['revision'],['sender'=>$senders[$i%count($senders)],'number'=>sprintf('R-DEMO-%04d',$i),'date'=>sprintf('2026-%02d-%02d',1+(($i-1)%9),1+(($i*3)%27)),'mode'=>$i%6===0?'items':'totals','currency'=>'EUR','accountId'=>(string)$accountsByCode['DEMO-'.(100+(($i%3)*100))],'net'=>'100.00','taxes'=>$i%6===0?[]:[['rate'=>$i%2?'19':'7','amount'=>$i%2?'19.00':'7.00']],'items'=>$i%6===0?[['description'=>'[DEMO] Position A','quantity'=>'2','unitNet'=>'20.00','unitGross'=>'23.80','priceBasis'=>'net','accountId'=>'','vatRate'=>'19'],['description'=>'[DEMO] Position B','quantity'=>'1','unitNet'=>'50.00','unitGross'=>'53.50','priceBasis'=>'gross','accountId'=>(string)$accountsByCode['DEMO-200'],'vatRate'=>'7']]:[]]); }
            $created[]=$id; }
        foreach (array_slice($created,-3) as $id) { $doc=$docs->get($admin,$id); $docs->status($admin,$id,(int)$doc['revision'],'trash'); }
    } finally { foreach (glob($tmp.'/*')?:[] as $file) @unlink($file); @rmdir($tmp); }
    echo 'Erzeugt: '.count($created)." eindeutig markierte Demo-Dokumente.\n";
} catch (Throwable $error) { fwrite(STDERR,($error instanceof PDOException?'Datenbankaktion fehlgeschlagen.':$error->getMessage())."\n"); exit(1); }
